SELECT DATE_TRUNC('MONTH', event_time) AS event_month, CASE WHEN duration_sec >= 486 THEN 'high' WHEN duration_sec >= 64 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, COUNT(duration_sec) AS duration_sec_count, MAX(event_time) AS latest_event_time FROM web_events GROUP BY 1, 2
